    },
    {
      "name": "MvPolynomial.eval₂_comp",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] (f : R →+* S₁)\n  (g : σ → R) (p : MvPolynomial σ R), f ((MvPolynomial.eval g) p) = MvPolynomial.eval₂ f (⇑f ∘ g) p"
    },
    {
      "name": "Polynomial.aeval_comp",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
